const mongoose = require('mongoose');
const { Schema } = mongoose;
// Mongoose Models have no .index(); delegate to the schema so Model.index(...) declarations work.
const model = (name, schema) => { const M = mongoose.model(name, schema); M.index = (...args) => schema.index(...args); return M; };
